# Iterating through a list
numbers = [1, 2, 3, 4, 5]
for num in numbers:
    print(num * 2)  # Multiply each number by 2

# Iterating through a tuple
colors = ("red", "green", "blue")
for color in colors:
    print(f"The color is {color}")

# Iterating through a dictionary
student = {"name": "John", "age": 20, "grade": "A"}

# Loop through keys
for key in student:
    print(key)  # Prints: name, age, grade

# Loop through values
for value in student.values():
    print(value)  # Prints: John, 20, A

# Loop through key-value pairs
for key, value in student.items():
    print(f"{key}: {value}")  # Prints: name: John, age: 20, grade: A

# Break statement example
for i in range(1, 11):
    if i == 5:
        break  # Exit the loop when i is 5
    print(i)

# Output: 1 2 3 4

# Continue statement example
for i in range(1, 6):
    if i == 3:
        continue  # Skip iteration when i is 3
    print(i)

# Output: 1 2 4 5

# Else clause with break
for i in range(1, 6):
    if i == 4:
        break
    print(i)
else:
    print("This won't execute because the loop was broken")

# Output: 1 2 3

# Equivalent to:
even_squares = []
for num in numbers:
    if num % 2 == 0:
        even_squares.append(num**2)

# Dictionary comprehension
numbers = [1, 2, 3, 4, 5]
squares_dict = {num: num**2 for num in numbers}
print(squares_dict)  # Output: {1: 1, 2: 4, 3: 9, 4: 16, 5: 25}

# Dictionary comprehension with condition
even_squares_dict = {num: num**2 for num in numbers if num % 2 == 0}
print(even_squares_dict)  # Output: {2: 4, 4: 16}

# Set comprehension
squares_set = {num**2 for num in numbers}
print(squares_set)  # Output: {1, 4, 9, 16, 25}

