# Find all prime numbers up to a limit

def is_prime(num):
    """Check if a number is prime"""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    # Check all numbers of form 6k±1 up to sqrt(num)
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6

    return True

# Find all primes up to limit
limit = 30
primes = []

for number in range(2, limit + 1):
    if is_prime(number):
        primes.append(number)

print(f"Prime numbers up to {limit}: {primes}")

# Alternative approach using list comprehension
primes_comprehension = [num for num in range(2, limit + 1) if is_prime(num)]
print(f"Using list comprehension: {primes_comprehension}")

